const isComponent = (item: Item): boolean => COMPONENT_TYPES.has(item.type);

const itemBasePremiums = (items: Item[]): number[] => {
  const mainBases = items
    .filter((item) => !isComponent(item))
    .map((item) => BASE_PREMIUMS[item.type]);

  const components = items.filter(isComponent);
  const componentBases = [...countByType(components).values()].map(
    componentGroupBase,
  );

  return [...mainBases, ...componentBases];
};
